"""OpenMM NPT driver — generated by pdb_wizard from openmm_npt.py template.

Placeholders are triple-brace tokens. The generator fills in force-field
XMLs, temperature, pressure, step counts, etc. Edit the rendered run.py
to tune the integrator, platform, or reporter settings.

Run:
    python {{{script_filename}}}

Outputs:
    trajectory.dcd  — coords every {{{report_interval}}} steps
    output.log      — energy / temperature / box (CSV)
    final.pdb       — last frame
"""
from openmm import (
    LangevinMiddleIntegrator,
    MonteCarloBarostat,
    Platform,
)
from openmm.app import (
    PME,
    DCDReporter,
    ForceField,
    HBonds,
    Modeller,
    PDBFile,
    PDBReporter,
    Simulation,
    StateDataReporter,
)
from openmm.unit import (
    angstrom,
    atmosphere,
    femtoseconds,
    kelvin,
    nanometer,
    picosecond,
    picoseconds,
)
import sys


pdb = PDBFile("{{{pdb_filename}}}")
forcefield = ForceField({{{forcefield_xmls}}})

modeller = Modeller(pdb.topology, pdb.positions)
# Add hydrogens / solvent here if needed:
#   modeller.addHydrogens(forcefield)
#   modeller.addSolvent(forcefield, padding=1.0 * nanometer)

system = forcefield.createSystem(
    modeller.topology,
    nonbondedMethod=PME,
    nonbondedCutoff={{{nonbonded_cutoff_nm}}} * nanometer,
    constraints=HBonds,
)

# NPT barostat
system.addForce(MonteCarloBarostat(
    {{{pressure_atm}}} * atmosphere,
    {{{temperature_k}}} * kelvin,
    25,
))

integrator = LangevinMiddleIntegrator(
    {{{temperature_k}}} * kelvin,
    1.0 / picosecond,
    {{{timestep_fs}}} * femtoseconds,
)

platform = Platform.getPlatformByName("CUDA")
try:
    simulation = Simulation(modeller.topology, system, integrator, platform)
except Exception:
    platform = Platform.getPlatformByName("CPU")
    simulation = Simulation(modeller.topology, system, integrator, platform)

simulation.context.setPositions(modeller.positions)
simulation.minimizeEnergy()

simulation.reporters.append(DCDReporter("trajectory.dcd", {{{report_interval}}}))
simulation.reporters.append(PDBReporter("final.pdb", {{{n_steps}}}))
simulation.reporters.append(StateDataReporter(
    sys.stdout, {{{report_interval}}},
    step=True, time=True, potentialEnergy=True, kineticEnergy=True,
    totalEnergy=True, temperature=True, volume=True, density=True,
    speed=True, separator="  ",
))
simulation.reporters.append(StateDataReporter(
    "output.log", {{{report_interval}}},
    step=True, time=True, potentialEnergy=True, kineticEnergy=True,
    totalEnergy=True, temperature=True, volume=True, density=True,
    separator=",",
))

simulation.step({{{n_steps}}})
print("done")
